      "materialText": "～ 105） 根据下列资料完成以下各题。 （2024 辽宁 101 2023 年前三季度， 规模以上文化企业 （简称文化企业） 实现营业收人 916 四亿元， 同比增长 7、 7％。 其中， 文化新业态特征较为明显的 16 个行业小类实现营业收人 36870 亿元， 同比增长巧.2％ 分产业类型看， 文化制造业实现营业收人 29007 亿元， 同比下降 1.0%； 文化批发和零售业巧 024 亿元， 同比增长 5.3％； 文化服务业 47588 亿元， 同比增长 14.6％。 分领域看， 文化核心领域实现营业收人 59507 亿元， 同比增长 12.4％； 文化相关领域 32112 亿元， 同比下降旧％。 分行业类别看， 新闻信息服务实现营业收人 12203 亿元， 同比增长 14、 9％； 内容创作生产 19857 亿元， 同比增长 103％； 创意设计服务 14973 亿元， 同比增长 9.6％； 文化传播渠道 107 ] 2 亿元， 同比增长 12.4 ‰ 文化投资运营 473 亿元， 同比增长 27.7％； 文化娱乐休闲服务 1289 亿元， 同比增长 67.2％； 文化生产和中介服务 10894 亿元， 同比下降巧％； 文化装备生产 4443 亿元， 同比下降 4， 3％； 文化消费终端生产 16775 亿元， 同比增长 2.1％。 分区域看， 东部地区实现营业收人 71959 亿元， 同比增长 8 」％； 中部地区 10600 亿元， 同比增长 1.9%； 西部地区 81％ 亿元， 同比增长 12.2 ‰ 东北地区 864 亿元， 同比增长 7.0％。 前三季度， 文化企业实现利润总额 7508 亿元， 同比增长 3L4％。 前三季度末， 文化企业资产总计 192849 亿元， 同比增长 6 7％。",
