      "materialText": "（2022 国考副省 131 ～ 135） 根据下列资料完成以下各题。 2020 年 12 月， C 市天然气用量为 9， 67 亿立方米， 同比增长 1L66％。 从供应结构看： 中石油供应 7.22 亿立方米， 同比增长 7， 44％； 中石化供应 2、 45 亿立方米， 同比增长 26.29％。 从用气结构看： 民用气为 3.98 亿立方米， 同比增长 16、 72％； CNG 用气 0.64 亿立方米， 同比下降 7.25％； 工业用气 5.05 亿立方米， 同比增长 10.75％。 2020 年， C 市天然气用量为 107.47 亿立方米， 同比增长 3.83％ 0 其中， 中石油供应 73.96 亿立方米， 同比增长 L72％； 中石化供应 33.51 亿立方米， 同比增长 & 8％。 从用气结构看： 民用气为 33， 75 亿立方米， 同比增长 5.4％； CNG 用气 6.99 亿立方米， 同比下降 13.92％； 工业用气 66.73 亿立方米， 同比增长 53％。 2021 年 2 月， c 市天然气用量为 9 引亿立方米， 同比增长 2L38％。 从供应结构看： 中石油供应 6.7 亿立方米， 同比增长 25.23％； 中石化供应 2， 61 亿立方米， 同比增长 12.5％。 从用气结构看： 民用气为 3 56 亿立方米， 同比增长 16.34％； CNG 用气 0 52 亿立方米， 同比增长 205 88％； 工业用气 5.23 亿立方米， 同比增长 079％。 2021 年 1 一 2 月， C 市天然气用量为 19、 21 亿立方米， 同比增长 12.8％。 其中， 中石油供应 14.23 亿立方米， 同比增长 1 & 88％； 中石化供应 4.98 亿立方米， 同比下降 L58％。 从用气结构看： 民用气为 7.78 亿立方米， 同比增长 12.75％； CNG 用气 L14 亿立方米， 同比增长 44.3％； 工业用气 10.29 亿立方米， 同比增长 10.17％。",
