      "materialText": "（2023 辽宁 1 16 ～ 120） 根据下列资料完成以下各题。 据对全国 6， 4 万家规模以上文化及相关产业企业调查， 2021 年前三季度， 上述企业实现营业收人 84205 亿元， 按可比口径计算， 同比增长 2L8％； 两年平均增长 10.0％。 分业态营业收人情况： 文化新业态特征较为明显的 16 个行业小类 28322 亿兀， 同比增长 26.1％； 两年平均增长 2 生 0％， 高于全部规模以上文化及相关产业企业 14.0 个百分点。 分行业类别营业收人情况： 新闻信息服务 9847 亿元， 同比增长 22.1％； 内容创作生产 17693 亿元， 同比增长 1 & 6％； 创意设计服务 13787 亿元， 同比增长 24， 0％； 文化传播渠道 9309 亿元， 同比增长 3 旧％； 文化投资运营 359 亿元， 同比垢长 13.8％； 文化娱乐休闲服务 916 亿元， 同比增长 35.3％； 文化辅助生产和中介服务 H441 亿元， 同比增长 1 & 3％； 文化装备生产 4880 亿元， 同比增长 17.8％； 文化消费终端生产巧 974 亿兀， 同比增长 22.0％。 分产业类型营业收人情况： 文化制造业 30950 亿元， 同比增长 17.7％； 文化批发和零售业 ] 3561 亿元， 同比增长 26 0％； 文化服务业 39693 亿元， 同比增长 23.7％。 分领域营业收人情况： 文化核心领域 51911 亿元， 同比增长 22.9％； 文化相关领域 32294 亿元， 同比增长 20.0％ 分区域营业收人情况： 东部地区 647 巧亿元， 同比增长 22.5％； 中部地区 1 1417 亿元， 同比增长 197％； 西部地区 7329 亿元， 同比增长 19.0％； 东北地区 744 亿元， 同比增长 20、 2％。 注： 部分数据因四舍五入， 存在总计与分项合计不等的情况。",
