      "materialText": "（2023 吉林 96 ～ 1 佣） 根据下列资料完成以下各题 2022 年， 规模以上工业企业实现营业收人 137.91 万亿元， 同比增长 5 9％； 发生营业成本 116.84 万亿元， 同比增长 7 」％； 营业收人利润率为 6.09％， 同比下降 0， 64 个百分点。 2022 年， 规模以上工业企业中， 分行业看： 采矿业实现利润总额 15573.6 亿元， 同比增长 48.6％； 制造业实现利润总额 64 巧 0.2 亿元， 同比下降 13.4％； 电力、 热力、 燃气及水生产和供应业实现利润总额 431 生 7 亿元， 同比增长 4L8％。 2022 年， 在 41 个工业大类行业中， 利润总额由高到低的前十个行业的利润情况如下： 煤炭开采和洗选业实现利润总额 10202 亿元， 同比增长 44.3％； 计算机、 通信和其他电子设备制造业实现利润总额 7389.5 亿元， 同比下降 13 」％； 化学原料和化学制品制造业实现利润总额 7302.6 亿元， 同比下降 8.7％； 电气机械和器材造业实现利润总额 59 巧.6 亿元， 同比增长 3 1 2％； 汽车制造业实现利润总额 5319.6 亿元， 同比增长 0.6％； 非金属矿物制品业实现利润总额 4759 亿元， 同比下降巧巧％； 医药制造业实现利润总额 428 & 7 亿元， 同比下降 3L8％； 石油和天然气开采业实现利润总额 3545 亿元， 同比增长 109.8％； 通用设备制造业实现利润总额 3250 3 亿元， 同比增长 0.4％； 电力、 热力生产和供应业实现利润总额 3 巧 4 亿元， 同比增长 86.3％。",
