      "materialText": "（2020 四川下 86 ～ 90） 根据下列资料完成以下各题。 20 巧年国民经济和社会发展统计公报。 公报显示， 全年全国居民人均可支配收人 21966 元， 比上年增长 & 9％， 增长率下降 1.2 个百分点。 按常住地分， 20 巧年城镇居民人均可支配收人 31195 元， 比上年增长 8 2％， 增长率比 2014 年下降 0 8 个白分点； 农村居民人均可支配收人 11422 元， 比上年增长 & 9％， 增长率比 2014 年下降 2.3 个百分点。 全年农村居民人均纯收人沩 10772 元。 全国农民工人均月收人 3072 元， 比上年增长 7， 2 ‰ 全国居民人均消费支出巧 712 元， 比上年增长 8.4％。 按常住地分， 城镇居民人均消费支出 21392 元， 增长 7， 1 ‰ 农村居民人均消费支出 9223 元， 增长 10.0％。 20 巧年， 全国参加城镇职工基本养老保险人数 35361 万人， 比上年末增加 1236 万人， 比 2013 年末增加 3133 万人； 参加城乡居民基本养老保险人数 50472 万人， 增加 365 万人， 比 2013 年末增加 772 万人。 参加城镇基本医疗保险人数 66570 万人， 增加 6823 万人， 比 2013 年末增加 9525 万人。 其中， 参加职工基本医疗保险人数 28894 万人， 增加 598 万人； 参加城镇居民基本医疗保险人数 37675 万人， 增加 6225 万人。 参加失业保险人数 17326 万人。 参加工伤保险人数 21404 万人， 增加 765 万人， 其中参加工伤保险的农民工 7489 万人， 增加 127 万人。 参加生育保险人数 17769 万人， 增加 730 万人。",
