      "materialText": "》 作业题 6 《 （2022 广东县级 86 ～ 90） 根据下列资料完成以下各题。 2020 年， 全国职工基本医疗保险 （以下简称职工医保） 参保人数持续增加， 基金收支规模基本稳定。 参加职工医保 34455 万人， 比上年同比增加巧 30 万人。 其中在职职工 25429 万人， 比上年增长 5 0％； 退休职工 9026 万人， 比上年增长 3.7％。 企业、 机关事业、 灵活就业等其他人员三类参保人员 （包括在职职工和退休人员） 分别为 23317 万人、 6387 万人、 4751 万人， 分别比上年增加 1050 万人、 巧 5 万人、 325 万人。 2020 年 2 一 7 月全国多地实施阶段性减半征收职工医保单位缴费， 累计减征约 1649 亿元， 全年职工医保基金 （含生育保险） 收人巧 732 亿元， 比上年减少 0， 7％； 支出 12867 亿元， 比上年增长 1.6％ 勹 2020 年， 职工医保统筹基金 （含生育保险） 收人 9145 亿元， 比上年减少 8 6％； 支出 7931 亿元， 比上年减少旧％； 当期结存 1214 亿元， 累计结存 15327 亿元。 2020 年， 职工医保个人账户收人 6587 亿元， 比上年增长 12、 8％； 支出 4936 亿元， 舍本部分题目解析见下册第 47 ～ 56 页。 比上年增长生 5％； 当期结存 1650 亿元， 累计结存 10096 亿元。 2020 年就诊量同比有所减少。 参加职工医保人员享受待遇 17.9 亿人次， 比上年减少巧.6％。 职工医保参保人员住院率巧.9％， 比上年下降 2、 8 个百分点。 其中： 在职职工住院率为 8、 6％， 比上年下降巧个百分点； 退休职工住院率为 36.0％， 比上年下降 65 个百分点。",
