      "materialText": "（2019 江苏 A 116 ～ 120） 根据下列资料完成以下各题。 2018 年国家统计局组织开展了第二次全国时间利用的随机抽样调查， 共调查 48580 人。 结果显示， 受访居民在一天的活动中， 有酬劳动平均用时 4 小时 24 分钟。 其中， 男性 5 小时巧分钟， 女性 3 小时 35 分钟； 城镇居民 3 小时 59 分钟， 农村居民 5 小时 1 分钟； 工作日 4 小时 50 分钟， 休息日 3 小时四分钟。 受访居民有酬劳动的参与率为 59， 0％， 其中城镇居民 53.1％。 受访居民无酬劳动平均用时 2 小时 42 分钟。 其中， 女性 3 小时 48 分钟； 农村居民 2 小时 39 分钟； 工作日 2 小时 34 分钟。 受访居民无酬劳动的参与率为 70 2％， 其中男性 55.3％。 无酬劳动包括家务劳动、 陪伴照料孩子生活、 护送辅导孩子学习、 陪伴照料成年家人、 购买商品或服务、 看病就医和公益活动。 受访居民家务劳动平均用时 1 小时 26 分钟， 参与率为 58.5％。 其中， 女性 2 小时 6 分钟， 参与率为 75， 6％。 受访居民陪伴照料孩子生活平均用时 36 分钟， 参与率为 1 & 9％； 护送辅导孩子学习平均用时 9 分钟， 参与率为 10.2％； 陪伴照料成年家人平均用时 8 分钟， 参与率为 5.0％； 看病就医平均用时 4 分钟， 参与率为 2.2％； 公益活动平均用时 3 分钟， 参与率为 4.1％。",
