      "materialText": "（2021 浙江 A 120） 根据下列资料完成以下各题。 2017 年， 国内旅游市场高速增长， 人出境市场平稳发展， 供给侧结构性改革成效明显。 国内旅游人数 50m 亿人次， 比上年同期增长旦 8％； 人出境旅游总人数 2.7 亿人次， 增长 3.7％； 全年实现旅游总收人 5.40 万亿元， 增长巧.1％； 全年全国旅游业对 GDP 的综合贡献为 9.13 万亿元， 占 GDP 总量的 1 1 04％； 旅游直接就业 2825 万人， 旅游直接和间接就业 7990 万人， 占全国就业总人口的 10.28％。、 全年国内旅游收人增长巧 9％ 2017 年， 国内旅游人数 50、 01 亿人次， 比上年同期增长 12， 8％ 其中， 城镇居民 36.77 亿人次， 增长巧.1 ‰ 农村居民 13， 24 亿人次， 增长 6， 8％。 国内旅游收人 457 万亿元， 增长巧， 9％。 其中， 城镇居民花费 3.77 万亿元， 增长 16.8％； 农村居民花费 0.80 万亿元， 增长 1L8％。、 全年人境过夜旅游人数增长 2.5％ 2017 年， 人境旅游人数 13948 万人次， 比上年同期增长 0.8％。 其中， 外国人 2917 万人次， 增长 3.6％； 香港同胞 7980 万人次， 下降 1 6％； 澳门同胞 2465 万人次， 增长 4.9％； 台湾同胞 587 万人次， 增长 2.5％。 人境旅游人数按照人境方式分， 船舶占 3.2％， 飞机占 16 巧％， 火车占 0 8％， 汽车占 22.2％， 其他占 57.2％。 2017 年， 人境过夜旅游人数 6074 万人次， 比上年同期增长 2.5％。 其中， 外国人 2248 万人次， 增长 3.8％； 香港同胞 2775 万人次， 增长 0.1％； 澳门同胞 522 万人次， 增长 8.6％； 台湾同胞 529 万人次， 增长 4.0％。、 全年国际旅游收人达 1234 亿美元 2017 年， 国际旅游收人 1234 亿美元， 比上年同期增长 2， 9％。 其中， 外国人在华花费 695 亿美元， 增长 4.1％； 香港同胞在内地花费 301 亿美元， 下降 1.5％； 澳门同胞在内地花费 83 亿美元， 增长 8.0％； 台湾同胞在大陆花费巧 5 亿美元， 增长 4.0％。 四、 全年人境外国游客亚洲占 74， 6％， 以观光休闲为目的游客占 37 彐％ 2m7 年， 人境外国游客人数 4294 万人次， 业洲占 74.6％， 美洲占 8.2％， 欧洲占 13.7％， 大洋洲占 2.1％， 非洲占 1.4%0 其中， 按照年龄分， 14 岁以下人数占 3.1％， 巧 ～ 24 岁占 13.2％， 25 一 44 岁占 49.9％， 45 ～ 64 岁占 29.2％， 65 岁以上占 4.6％； 按性别分， 男占 60.7％， 女占 3 归％； 按目的分， 会议 ／ 商务占 133％， 观光休闲占 37.以， 探亲访友占 2， 6％， 服务员工占 1 生 8％， 其他占 32.2％。 2017 年， 按人境旅游人数排序， 我国主要客源市场前 17 位国家如下： 缅甸、 越南、 韩国、 日本、 俄罗斯、 美国、 蒙古、 马来西亚、 菲律宾、 新加坡、 印度、 加拿大、 泰国、 澳大利亚、 印度尼西亚、 德国、 英国。 五、 全年中国公民出境旅游人数达 1305 ] 万人次 2017 年， 中国公民出境旅游人数 13051 万人次， 比上年同期增长 7.0％。， 全国人境旅游人数较出境旅游人数多多少万人次？",
