      "materialText": "（20 四安徽％ ～ 100） 根据下列资料完成以下各题。 20 [ 4 年我国实施 “ 单独两孩 \" 生育政策， 出生人口 1687 万人， 比上年增加 47 万人。 2016 年实施 “ 全面两孩 \" 生育政策， 出生人凵 1786 万人， 比上年增加 131 万人； 出生率与 “ 十二五 \" 时期年平均出生率相比， 提高了 0， 84 个千分点。 2017 年我国出生人口 1723 万人， 虽然比上年减少 63 万人， 但比 “ 十二五 ” 时期年平均出生人口多出 79 万人； 出生率为 12.43 ‰， 比上一年降低巧 2 个千分点。 2017 年二孩数量进一步上升至 883 万人， 二孩占全部出生人口的比重达到 5L2％， 比 2016 年的占比提高了 ] 1 个百分点。 2017 年出生人口最多的省份是山东， 出生人口 174.98 万人， 但是比 2016 年减少 2， 08 万人。 丿、 东和河南出生人口也超过百万， 其中广东出生人凵巧 L63 万人， 同比增加旦 18 万人； 河南出生人口 140.13 万人， 较上年减少 2 48 万人。 此外， 出生人口排名前十的省份依次还有河北、 四川、 湖南、 安徽、 广西、 江苏、 湖北。 其中， 河北、 四川、 湖南出生人口超 90 万人， 湖北最少， 为 74， 26 万人。 从人口增量来看， 2017 年广东出生人口增量最大， 出生人口较 2016 年增加 22.18 万人。 安徽、 四川、 河北出生人口增量超过 5 万， 此外， 江苏、 湖南、 山东、 河南出生人口较 2016 年有所减少。 其中， 河南减少最多， 出生人口减少 2.48 万人。",
