      "materialText": "《 作业题 9 《 （2022 四川下 96 ～ 100 〕 根据下列资料完成以下各题。 2020 年末， 全国共有艺术表演团体 17581 个， 比上年末减少 214 个； 从业人员 43.69 万人， 增加 244 万人。 其中各级文化和旅游部门所属艺术表演团体 2060 个， 占 1L7％， 从业人员 1075 万人， 占 24.6％。 2020 年， 全国艺术表演团体共演出 225.61 万场， 比上年下降 24.0％； 国内观众 8.93 亿人次， 下降 27， 4％； 演出收人 86.63 亿兀， 下降 3L7％。 本部分题目解析见下册第 76 ～ 84 页。 2020 年， 全国文化和旅游部门所属艺术表演团体共组织政府采购公益演出 13， 38 万场， 比上年下降 14.9％； 观众 0.86 亿人次， 下降 27、 9％。 2020 年末， 全国公共图书馆实际使用房屋建筑面积 1785， 77 万平方米， 比上年末增长 12， 2％； 全国图书总藏量 117929.99 万册， 增长 6 1％； 阅览室座， 席数 126.47 万个， 增长 6， 2％； 计算机 226234 台， 增加 419 台； 其中供读者使用的电子阅览终端 143714 台， 减少 2022 台 2020 年末， 全国共有群众文化机构 43687 个， 比上年末减少 386 个。 其中乡镇综合文化站 32825 个， 减少 705 个。 年末全国群众文化机构从业人员 185076 人， 比上年末减少 4992 人。 其中具有高级职称的人员 7075 人， 具有中级职称人员 17％ 9 人。",
