      "materialText": "（2019 四川下 86 ～ 90） 根据下列资料完成以下各题。 2016 年 4 月， 保监会机关及各保监局共接收各类涉及保险消费者权益的有效投诉总量为 2989 件， 同比上升 43， 巧％， 环比上升 24.44％。 其中， 接收保险公司投诉 2980 件， 其他非保险公司投诉 9 件。 接收保险公司投诉中， 涉及保险公司合同纠纷类投诉 2721 件； 涉及保险公司违法违规类投诉 259 件。 所接收的 2980 件保险公司投诉中， 财产险公司的投诉为巧 10 件。 其中， 投诉量位居前 10 的财产险公司的投诉量总和占投诉所有公司投诉总量的 78 68％。 人身险公司的投诉为 1470 件。 其中， 投诉量位居前 10 的人身险公司的投诉量总和占所有公司投诉总量的 85.37％。 另外， 人身险涉及保险合同纠纷的投诉有 1281 件， 其中销售纠纷 481 件， 理赔纠纷 357 件， 保全纠纷 237 件。",
