      "materialText": "《 作业题 10 《 （2020 国考副省 131 ～ 135） 根据下列资料完成以下各题。 2018 年前三季度， S 省社会物流总额 35357.26 亿元， 同比增长 64％， 增速比上半年放缓 0.7 个百分点。 其中， 工业品物流总额 16636.巧亿元， 同比增长 0， 2％， 增速比上半年放缓 2.1 个百分点； 外部流人 （含进口） 货物物流总额 17357 引亿元， 同比增长 12 1%， 增速比上半年加快 0.8 个百分点； 农产品物流总额 875.06 亿元， 同比增长 1L6％， 增速比上半年加快 0.5 个百分点； 单位与居民物品物流总额 457.86 亿元， 同比增长 40.7％， 增速比上半年放缓 3 个百分点； 再生资源物流总额 30 88 亿元， 同比下降 7.0％， 降幅比上半年扩大 4.3 个百分点。 2018 年前三季度， s 省物流相关行业实现总收入 19 旦 8 亿元， 同比增长 6.6％。 其中： 运输环节收人 132L9 亿元， 同比增长 6， 0％； 保管环节收人 226.2 亿兀， 同比增长 6， 4％； 邮政业收人 82， 8 亿元， 同比增长伍 7％； 配送、 加工、 包装业收人 98.8 亿元， 同比增长 6.4％。 2018 年前三季度， S 省社会物流总费用 2682.1 亿元， 同比增长 6.3％， 比上半年放缓 0.9 个百分点。 其中： 物流运输环节总费用 1854.6 亿元， 同比增长 6.3％； 保管环节总费用 612.4 亿兀， 同比增长 6.4％； 管理环节总费用 214.9 亿元， 同比增长 6， 4％。",
