      "materialText": "》 作业题 1 《 （2024 青海 116 一 120） 根据下列资料完成以下各题。 2022 年， 全国共有 260 家银行机构和 29 家理财公司累计新发理财产品 2.94 万只， 同比下降 38.23％， 降幅比上年同期扩大 7.22 个百分点； 累计募集资金 89.62 万亿元， 同比减少 32 57 万亿元。 截至 2022 年底， 全国共有 278 家银行机构和 29 家理财公司有存续的理财产品， 共存续产品 3.47 万只， 同比下降生 41％； 存续规模 27.65 万亿元， 同比下降 4.66％。 分机构类型来看， 理财公司存续产品 13947 只， 存续规模 22.24 万亿元， 同比增长 29.36％。 银行机构中， 城商行存续产品 9064 只， 存续规模 245 万亿元， 同比下降 32.34％； 农村金融机构存续产品 7808 只， 存续规模 L09 万亿元， 同比下降 2， 63％； 股份制银行存续产品 1208 只， 存续规模 0 88 万亿元， 同比下降 82.99％； 大型银行存续产品 668 只， 存续规模 0.92 万亿元， 同比下降 4926％； 其他机构存续产品 1980 只， 存续规模 0， 07 万亿元， 同比下降 13.42％。 截至 2022 年底， 持有理财产品的投资者数量为 967 L27 万个， 较年初增长 18.96％， 其中机构投资者数量为 95、 95 万个， 数量占比同比提升了 0 22 个百分点； 在持有理财产品的个人投资者中， 数量最多的是风险偏好为二级 （稳健型 〕 的投资者， 占比 35 44％。",
