      "materialText": "（四） （2023 国考行政执法 126 ～ 130） 根据下列资料完成以下各题。 2021 年， 全国纺织品服装出口 3155 亿美元， 同比增长 & 4％。 其中， 纺织品出口 1452.2 亿美元， 同比下降 5.6％， 较 2019 年增长 22 0％； 服装出口 1702.8 亿美元， 同比增长 24， 0％， 较 2019 年增长 16.0％。 其中， 针织服装及衣着附件出口 864.8 亿美元， 同比增长 39 0％； 梭织服装及衣着附件出凵 701 2 亿美元， 同比增长 12.6％。 2021 年， 中国对美国、 东盟、 欧盟和日本的纺织品服装出口合计 1724.9 亿美元。 其中， 对美国出口额为 563.5 亿美元， 同比增长 4.0％； 向东盟十国出口纺织品服装 491.2 亿美元， 同比增长 24.9％； 对欧盟 27 国出囗纺织品服装 469.9 亿美元， 同比下降 1％； 对日本出口纺织品服装 200.3 亿美元， 同比下降 7.2％。 2021 年， 中国向全球出口纺织纱线 138 亿美元， 出口织物 667 亿美元， 分别同比增长 4 巧％ 和 34 3％。 纺织制品当中， 防疫类口罩出口额为 129， 5 亿美元， 出口金额、 数量同比分别下降 76.0％ 和 13 0％。 除防疫类口罩外， 其他纺织制品出口额为 502 亿美元， 同比增长 27.5％。 2021 年， 中国向 “ 一带一路 ” 沿线国家出口纺织品服装 H37.9 亿美元， 同比增长 24， 5％， 较 2019 年增长 17.3％； 同时， 中国自 “ 一带一路 \" 沿线国家进口纺织品服装 13L6 亿美元， 同比增长 24.5％。",
