      "materialText": "（2023 福建 106 ～ 110） 根据下列资料完成以下各题。 2022 年 1 一 7 月， 全国规模以上工业发电 477 万亿千瓦时， 同比增长 1.4%， 增速比上半年加快 0.7 个百分点。 7 月份， 全国发电量 8059 亿千瓦时， 同比增长 4 巧％， 增速比上月加快 3.0 个百分点。 分品种看， 7 月份火电由降转增， 同比增长 5.3％； 由于来水偏枯， 水电同比增长 2.4％， 增速比上月放缓 266 个百分点； 风电同比增长 5.7％， 增速比上月放缓 11 0 个百分点； 核电同比下降 3 3％， 降幅比上月收窄 5.7 个百分点； 太阳能发电同比增长 13 0％， 增速比上月加快 3.1 个百分点。 2022 年 1 一 7 月， 全社会用电量累计 49303 亿千瓦时， 同比增长 3.4％。 分产业看， 第一产业用电量 634 亿千瓦时， 同比增长 1L1％； 第二产业用电量 32552 亿千瓦时， 同比增长 1 1％； 第三产业用电量 8531 亿千瓦时， 同比增长 4、 6％； 城乡居民生活用电量 7586 亿干瓦时， 同比增长 12.5％。 7 月份， 全社会用电量 8324 亿十时， 同比增长 6、 3％。 分产业看， 第一产业用电量 121 亿千瓦时， 同比增长 14 3％； 第二产业用电量 5132 亿千瓦时， 同比下降旧％； 第三产业用电量巧 91 亿千瓦时， 同比增长 II.5％； 城乡居民生活用电量 1480 亿千瓦时， 同比增长 26.8％。",
