      "materialText": "（2021 北京乡镇 126 ～ 130） 根据下列资料完成以下各题。 2016 年全国女性就业人员占全社会就业人员的比重为 43.1％， 其中城镇单位女性就业人员 6518 万人， 比 2010 年增加 1656 万人。 2016 年公有制企事业单位中女性专业技术人员 1480 万人， 比 2010 年增加 211 万人， 所占比重达 47.8％， 提高 2.8 个百分点； 其中女性高级专业技术人员 16 ] 万人， 比 2010 年增加 59.3 万人， 所占比重 38.3％， 提高 3 个百分点。 2016 年企业董事会中女职工董事占职工董事的比重为 39.9％， 企业监事会中女职工监事占职工监事的比重为 4 旧％， 比 2m0 年分别提高 7.2 和 4.9 个百分点； 企业职工代表大会中女性代表比重为 2 & 7％， 略低于 2010 年 0.3 个百分点。 2016 年女性参加生育保险的人数达 8020 万人， 比 2010 年增长 49％。 2016 年， 参加城镇职工基本医疗保险的女性 1.4 亿人， 比 20H 年增长 2L5％； 参加城镇居民基本医疗保险的女性 1.9 亿人， 比 2011 年增长了 1.5 倍。 2016 年全国参加城镇职工基本养老保险人数 3.8 亿人， 其中女性 1.8 亿人， 占比比 2m0 年提高 3 个百分点； 2016 年， 参加城乡居民基本养老保险人数 5、 1 亿人， 其中女性超过 1.7 亿人。 2016 年全国参加失业保险的人数超过 1.8 亿人， 其中女性 7551 万人， 分别比 2010 年增加 4713 万人和 2402 万人， 增长约 35％ 和 47％； 参加工伤保险人数 2.2 亿人， 其中女性 8129 万人， 分别比 2010 年增加 5728 万人和 2429 万人， 增长约 35％ 和 43％。",
