      "materialText": "（四 〕 （2021 四川下 91 ～ 95） 根据下列资料完成以下各题。 2016 年， 全国棉花产量 534、 3 万吨， 比 20 巧年减产 260 万吨。 播种面枳减少是 2016 年我国棉花产量减少的主要原因。 继 2014、 20 巧年后， 2016 年相花播种面积继续减少。 2016 年全国棉花播种面积为 3376.1 千公顷， 比 20 巧年减少 420.5 千公顷。 分地区看， 新疆棉花播种面积比 20 巧年减少 99， 1 千公顷， 下降约 5.2％； 其他省棉花播种面积减少 32L3 千公顷， 下降约 17％。 从棉区看， 黄河、 长江流域棉区延续 20 巧年减产较多的趋势。 其中， 黄河流域棉花播种面积减少 147.8 千公顷， 下降约 14.3％； 单产每公顷增加 633 公斤， 提高约 6、； 产量减少 10.0 万吨， 下降约 9.2％。 长江流域棉花播种面积减少 160.7 千公顷， 下降约 19.8％； 单产每公顷减少 68.3 公斤， 下降约 5.9％； 产量减少 23， 0 万吨， 下降约 24.6％。 尽管我国最大的产棉区一一新疆棉花播种面积减少， 但由于每公顷单产增加巧 1.5 公斤， 棉花产量仍达到 359， 4 万吨， 比上年增加 9.1 万吨， 增长约 26％。 新疆棉花产量占全国的比重进一步扩大到约 67.3％， 比上年提高约 4 8 个百分点。",
