      "materialText": "（2020 四川 96 ～ 100） 根据下列资料完成以下各题。 2017 年， S 市服务业小微样本企业总体实现营业收人 105.39 亿元， 同比增长 3 彐％， 比 2016 年回落了巧、 7 个百分点， 户均实现营业收人 510， 63 万元。 2017 年， S 市服务业小微样本企业总体资产 938， 58 亿元， 同比增长 4.2％， 增速比 2016 年下降 0.9 个百分点， 户均资产 4547.40 万元。 分门类看， 除房地产业， 交通运输、 仓储和邮政业， 教育业资产总计比 2016 年分别下降 3 彐％、 5.4％ 和 6.8％ 外， 其他行业资产总计同比均有不同程度的增长。 2017 年， s 市服务业小微样本企业总体营业税金及附加为 L09 亿元， 同比下降 29.5％； 激纳增值税 2.30 亿元， 同比增长 1L6％， 户均缴纳增值税 1L16 万元。 2017 年， s 市服务业小微样本企业总体应付职工薪酬 1928 亿元， 比 2 田 6 年增长 9.3％。 户均应付职工薪酬 93.50 万元。 从业人员人数 29028 人， 人均年薪酬 6.64 万元， 比 2016 年增加 0.60 万元。",
