      "materialText": "《 作业题 10 》 （2021 黑龙江 111 ～ 1 巧） 根据下列资料完成以下各题。 截至 2019 年 12 月 31 日， 中国共产党党员总数为 9 四 1.6 万名， 同比增长 L46％。 在党员的性别、 民族和学历上， 女党员 2559.9 万名， 少数民族党员 680.3 万名， 大专及以上学历党员 466 巧万名。 在党员的人党时间上， 新中国成立前人党的 17、 4 万名， 新中国成立后至党的十一届三中全会前人党的巧 50.9 万名， 党的十一届三中全会后至党的十八大前人党的 6127.7 万名， 党的十八大以来人党的 1495 6 万名。 在党员的职业上， 工人 （含工勤技能人员） 644.5 万名， 农牧渔民 2556.1 万名， 企事业单位、 社会组织专业技术人员 1440.3 万名， 企事业单位、 社会组织管理人员 1010.4 万名， 党政机关工作人员 767.8 万名， 学生 196， 0 万名， 其他职业人员 710， 4 万名， 离退休人员 1866.1 万名。 本部分题目解析见下册第 336 ～ 345 页。 2019 年共发展党员 234.4 万名， 比上年增长且 06％。 其中， 发展女党员 99.4 万名， 占 42、 4％； 发展少数民族党员 23.6 万名， 占 1 旧％； 发展 35 岁及以下党员 188.3 万名， 占 80、 3％； 发展具有大专及以上学历的党员 106， 8 万名， 占 45.6％。 发展党员的职业上， 工人 （含工勤技能人员） 14、 3 万名， 企事业单位、 社会组织专业技术人员 3L6 万名， 企事业单位、 社会组织管理人员 25.3 万名， 农牧渔民 42.4 万名， 党政机关工作人员 13.4 万名， 学生 84.4 万名， 其他职业人员 22.9 万名。 61 岁及以上 2657、 7 56、 岁 745.1 51 一 55 岁 879.4 46、 50 岁 936.2 41、 45 岁 8.4 36、 40 岁 882.7 31、 35 岁 994.6 30 岁及以下 123L5 0 500 1000 巧 00 2000 2500 3000 截至 2019 年 12 月 31 日中国共产党党员年龄构成 （单位： 万名）",
