      "materialText": "（2021 国考地市 121 ～ 125） 根据下列资料完成以下各题。 截至 20 四年末， 全国已有残疾人康复机构 9775 个， 比 2018 年增长 739 个。 2019 年， 1043.0 万残疾儿童及持证残疾人得到基本康复服务， 其中包括 0、 6 岁残疾儿童 18.1 万人。 个 1 〔 旧 00 9 開 0 8 開 0 7000 6m0 5 佣 0 9775 9036 8334 4 佣 0 7858 7111 6914 3 佣 0 2000 1000 0 2014 年 2015 年 2016 年 201 芦阝 2018 年 2019 钎： 图 1 2014 一 2019 年各年末全国残疾人康复机构数量辅助器具服务 1970 视力残疾康复服务 1430 听力言语残疾康复服务 1669 精神残疾康复服务 2022 孤独症丿 L 童康复服务 2238 智力残疾康复服务 3529 肢体残疾康复服务 4312 500 1000 巧 00 2000 2500 3000 3 500 4 開 0 4500 个 0 图 2 2019 年末提供不同类型服务的残疾人康复机构数量截至 2019 年末， 全国已竣工的各级残疾人综合服务设施 2341 个， 总建设规模 584， 5 万平方米， 总投资 183.1 亿元； 已竣工各级残疾人康复设施 1006 个， 总建设规模 4 ] 4， 2 万平方米， 总投资 132.2 亿元。",
