          "text": "2019 年末， 提供肢体残疾康复服务的康复机构的数量占全国残疾人康复机构总数的比重， 比提供精神残疾康复服务的康复机构的数量占全国残疾人康复机构总数的比重高约多少个百分点 A. 13 B. 18 C. 23 D. 28",
