          "text": "如提供视力残疾康复服务的残疾人康复机构中， 同时提供听力言语残疾康复服务的机构比不提供该服务的机构多 20％， 则 2019 年末全国有多少家残疾人康复机构不提供以上两种康复服务中的任意一种？ B. 7300 ～ 7600 家之间 A. 不到 73 佣家 D. 超过 79 佣家 C. 7600 ～ 7900 家之间",
