      "materialText": "《 作业题 6 《 （2023 辽宁 101 ～ 105） 根据下列资料完成以下各题。 据国家统计局数据显示， 2021 年我国研究与试验发展 (R&D） 经费支出 27864 亿元， 同比增长 14.2％， 占国内生产总值之比为 2.44％， 其中基础研究经费 1696 亿元。 国家自然科学基金共资助 4.87 万个项目。 2021 年全年授予专利权 460.1 万件， 同比增长 26.4％； PCT 专利申请受理量 73 万件。 截至 2021 年末， 有效专利巧 42.1 万件， 其中境内有效发明专利 270.4 万件。 每万人口高价值发明专利拥有量 7.5 件。 全年商标注册 773.9 万件， 同比增长 34.3％。 全年共签订技术合同 67 万项， 技术合同成交金额 37294 亿元， 同比增长 32.0％ 2021 年专利授权和有效专利情况同比增长 （％） 专利数 （万件） 指标 26.4 专利授权数 460.1 27.0 其中： 境内专利授权 445.1 其中： 发明专利授权 69.6 33.2 其中： 境内发明专利 57.8 年末有效专利数 1542.1 28、 6 其中， 境内有效专利 1429.5 17.6 其中： 有效发明专利 359 7 22.2 其中： 境内有效发明专利 270.4 舍本部分题目解析见下册第引 3 ～ 422 页。 30m0 27864 24393 25m0 22144 19678 20000 17606 巧佣 0 10000 5m0 0 2017 年 2018 年 2019 年 2020 年 202 ] 年 2017 一 2021 年我国研究与试验发展 （R&D） 经费支出 （单位： 亿元）",
